<script setup lang="ts">
import type { Settings } from '../../game/services/storage';
import DialogFrame from './DialogFrame.vue';
import { vPad } from '../gamepadNavigation';
const props = defineProps<{ settings: Settings }>(); const emit = defineEmits<{ change: [settings: Settings]; close: [] }>();
function volume(event: Event) { if (event.target instanceof HTMLInputElement) emit('change', { ...props.settings, volume: Number(event.target.value) }); }
function visuals(event: Event) { if (event.target instanceof HTMLInputElement) emit('change', { ...props.settings, effectsIntensity: Number(event.target.value) }); }
function category(key: 'musicVolume' | 'sfxVolume', event: Event) { if (event.target instanceof HTMLInputElement) emit('change', { ...props.settings, [key]: Number(event.target.value) }); }
function adjust(key: 'volume' | 'musicVolume' | 'sfxVolume' | 'effectsIntensity', step: number, direction: -1 | 1) {
  const fallback = { volume: .3, musicVolume: .32, sfxVolume: .8, effectsIntensity: .7 };
  const value = Math.round(Math.max(0, Math.min(1, (props.settings[key] ?? fallback[key]) + step * direction)) * 100) / 100;
  emit('change', { ...props.settings, [key]: value });
}
</script>
<!-- Ultimate accessibility controls use the same persisted settings and gamepad navigation. -->
<template><DialogFrame label="Настройки" @close="emit('close')"><small>ПОД СВОЙ РИТМ</small><h1>Настройки</h1><label class="setting">Общая громкость <span>{{ Math.round(settings.volume * 100) }}%</span><input v-pad="{ adjust: direction => adjust('volume', .05, direction) }" aria-label="Громкость" type="range" min="0" max="1" step="0.05" :value="settings.volume" @input="volume"></label><label class="setting">Музыка <span>{{ Math.round((settings.musicVolume ?? 0.32) * 100) }}%</span><input v-pad="{ adjust: direction => adjust('musicVolume', .01, direction) }" aria-label="Музыка" type="range" min="0" max="1" step="0.01" :value="settings.musicVolume ?? 0.32" @input="category('musicVolume', $event)"></label>
<label class="setting">Эффекты (SFX) <span>{{ Math.round((settings.sfxVolume ?? 0.8) * 100) }}%</span><input v-pad="{ adjust: direction => adjust('sfxVolume', .01, direction) }" aria-label="Эффекты (SFX)" type="range" min="0" max="1" step="0.01" :value="settings.sfxVolume ?? 0.8" @input="category('sfxVolume', $event)"></label>
<label class="setting inline"><span>Выключить звук</span><input type="checkbox" :checked="settings.muted" v-pad="() => emit('change', { ...settings, muted: !settings.muted })" @change="emit('change', { ...settings, muted: !settings.muted })"></label><div class="setting inline"><span>Масштаб пикселей</span><div><button class="small-button" :aria-pressed="settings.pixelScale === 2" v-pad="() => emit('change', { ...settings, pixelScale: 2 })" @click="emit('change', { ...settings, pixelScale: 2 })">2×</button> <button class="small-button" :aria-pressed="settings.pixelScale === 3" v-pad="() => emit('change', { ...settings, pixelScale: 3 })" @click="emit('change', { ...settings, pixelScale: 3 })">3×</button></div></div><label class="setting">Интенсивность эффектов<input v-pad="{ adjust: direction => adjust('effectsIntensity', .1, direction) }" aria-label="Интенсивность эффектов" type="range" min="0" max="1" step="0.1" :value="settings.effectsIntensity ?? 0.7" @input="visuals"></label><label class="setting inline"><span>Цифры урона</span><input type="checkbox" :checked="settings.damageNumbers ?? false" v-pad="() => emit('change', { ...settings, damageNumbers: !settings.damageNumbers })" @change="emit('change', { ...settings, damageNumbers: !settings.damageNumbers })"></label><label class="setting inline"><span>Меньше движения</span><input type="checkbox" :checked="settings.reducedMotion ?? false" v-pad="() => emit('change', { ...settings, reducedMotion: !settings.reducedMotion })" @change="emit('change', { ...settings, reducedMotion: !settings.reducedMotion })"></label><label class="setting inline"><span>Меньше вспышек</span><input type="checkbox" :checked="settings.reducedFlash ?? false" v-pad="() => emit('change', { ...settings, reducedFlash: !settings.reducedFlash })" @change="emit('change', { ...settings, reducedFlash: !settings.reducedFlash })"></label><p class="muted">Сохраняется только в этом браузере.</p><button v-pad="() => emit('close')" @click="emit('close')">Готово</button></DialogFrame></template>
